  type: 'quote',
  label: 'Quote',
  schema: z.object({
    text: textSchema,
    author: textSchema.optional(),
  }),
  defaults: { text: 'Say it once.', author: 'Someone wise' },
  variants: ['centered', 'split'],
  defaultVariant: 'centered',
  optional: { props: ['author'] },
  wireframe: quoteWireframe,
})

